// Minimal Azure Function (Node.js) illustrating the idea
const redis = require('ioredis')({ /* config */ })
const rateLua = `
  local tokens = tonumber(redis.call('GET', KEYS[1]) or '0')
  if tokens > 0 then
    redis.call('DECR', KEYS[1])
    return 1
  else
    return 0
  end
`;
module.exports = async function (context, req) {
  const tenant = req.headers['x-tenant-id'];
  const key = `rate:${tenant}`;
  const allowed = await redis.eval(rateLua, 1, key);
  if (!allowed) { context.res = { status: 429 }; return; }
  // idempotent path would check req.headers['x-request-id'] and store result
  context.res = { status: 200, body: 'accepted' };
};
```

